{"contents":[{"uri":"montagent://schema/element/image.json","mimeType":"application/json","text":"{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "id": {
      "type": "string"
    },
    "type": {
      "type": "string",
      "const": "image"
    },
    "group": {
      "type": "string"
    },
    "start": {
      "type": "integer",
      "format": "int64"
    },
    "end": {
      "type": "integer",
      "format": "int64"
    },
    "layer": {
      "$ref": "montagent://schema/def/Layer.json"
    },
    "source": {
      "type": "string",
      "description": "Inline, never an asset-table reference (ADR-0002)."
    },
    "x": {
      "$ref": "montagent://schema/def/Animatableint64.json"
    },
    "y": {
      "$ref": "montagent://schema/def/Animatableint64.json"
    },
    "origin": {
      "$ref": "montagent://schema/def/Origin.json"
    },
    "width": {
      "type": "integer",
      "format": "int64",
      "description": "Required, never defaulted: the source's dimensions are not in the document, so a\nnatural-size default would make the element's rendered rect unreadable — and it\nwould fail *quietly*, because a centre-cropped photo looks plausible (ADR-0012)."
    },
    "height": {
      "type": "integer",
      "format": "int64"
    },
    "fit": {
      "$ref": "montagent://schema/def/Fit.json",
      "description": "Required on every element carrying a raster source; omission is a schema error\nnaming the three values (ADR-0015)."
    },
    "clip": {
      "type": "array",
      "items": {
        "type": "integer",
        "format": "int64"
      },
      "minItems": 4,
      "maxItems": 4
    },
    "scale": {
      "$ref": "montagent://schema/def/AnimatableArray_size_2_of_double.json"
    },
    "rotation": {
      "description": "Degrees clockwise, and **never normalised into `[0,360)`** — `1080` is three turns,\nand a writer that wraps it silently renders one third of the motion.",
      "$ref": "montagent://schema/def/Animatabledouble.json"
    },
    "opacity": {
      "$ref": "montagent://schema/def/Animatabledouble.json"
    },
    "effects": {
      "type": "array",
      "items": {
        "$ref": "montagent://schema/index.json#/effects"
      }
    }
  },
  "required": [
    "id",
    "type",
    "start",
    "end",
    "source",
    "width",
    "height",
    "fit"
  ],
  "description": "`source, x, y, origin, width, height, fit, clip, scale` — ADR-0041's measured order —\nthen the two transform properties ADR-0012 declares after `scale`, then `effects`."
}
"}]}

